# account_config.py# Shared configuration and global variables using a singleton classimport osimport jsonimport timefrom datetime import datetimeimport requestsfrom typing import Optional, Dict, Any# ==================== Encryption Utilities ====================import base64import hashlibfrom cryptography.fernet import Fernetfrom cryptography.hazmat.primitives import hashesfrom cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMACSECRET = b"latigo_platform_secure_key_2024"SALT = b"latigo_salt_2024"def _get_cipher():    kdf = PBKDF2HMAC(        algorithm=hashes.SHA256(),        length=32,        salt=SALT,        iterations=100000,    )    key = base64.urlsafe_b64encode(kdf.derive(SECRET))    return Fernet(key)def encrypt_data(data):    if data is None:        return None    try:        cipher = _get_cipher()        encrypted = cipher.encrypt(str(data).encode('utf-8'))        return base64.urlsafe_b64encode(encrypted).decode('utf-8')    except Exception as e:        print(f"⚠️ Encryption error: {e}")        return datadef decrypt_data(encrypted_data):    if encrypted_data is None:        return None    try:        cipher = _get_cipher()        encrypted_bytes = base64.urlsafe_b64decode(encrypted_data.encode('utf-8'))        decrypted = cipher.decrypt(encrypted_bytes)        return decrypted.decode('utf-8')    except Exception as e:        print(f"⚠️ Decryption error: {e}")        return encrypted_datadef get_token_txt_path():    """Get the path to token.txt in the account folder"""    base_dir = os.path.dirname(os.path.abspath(__file__))    account_dir = os.path.join(base_dir, "account")    os.makedirs(account_dir, exist_ok=True)    return os.path.join(account_dir, "token.txt")def save_token_txt(token):    """Save token to account/token.txt with encryption"""    if token is None:        return False    try:        token_txt_path = get_token_txt_path()        encrypted_token = encrypt_data(token)        with open(token_txt_path, 'w', encoding='utf-8') as f:            f.write(encrypted_token)        print(f"✅ Token saved to account/token.txt (encrypted)")        return True    except Exception as e:        print(f"❌ Failed to write token.txt: {e}")        return Falsedef load_token_txt():    """Load token from account/token.txt with decryption"""    try:        token_txt_path = get_token_txt_path()        if not os.path.exists(token_txt_path):            return None        with open(token_txt_path, 'r', encoding='utf-8') as f:            encrypted_token = f.read().strip()        if not encrypted_token:            return None        decrypted_token = decrypt_data(encrypted_token)        return decrypted_token    except Exception as e:        print(f"❌ Failed to read token.txt: {e}")        return Nonedef remove_token_txt():    """Remove account/token.txt file"""    try:        token_txt_path = get_token_txt_path()        if os.path.exists(token_txt_path):            os.remove(token_txt_path)            print(f"✅ account/token.txt removed")            return True    except Exception as e:        print(f"❌ Failed to remove token.txt: {e}")    return Falsedef remove_old_token_txt():    """Remove old token.txt from main directory (cleanup)"""    try:        old_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "token.txt")        if os.path.exists(old_path):            os.remove(old_path)            print(f"✅ Old token.txt removed from main directory")            return True    except Exception as e:        print(f"⚠️ Could not remove old token.txt: {e}")    return False# ==============================================================class TokenManager:    """Manages token storage and retrieval with encryption"""        TOKEN_FILE = os.path.join(os.path.dirname(__file__), "token_data.json")        @classmethod    def save_tokens(cls, user_id, access_token, refresh_token, expires_in, user_data=None):        """Save tokens to file with encryption"""        expires_at = time.time() + expires_in                # Encrypt sensitive data before saving        encrypted_data = {            "user_id": encrypt_data(str(user_id)) if user_id else None,            "access_token": encrypt_data(access_token) if access_token else None,            "refresh_token": encrypt_data(refresh_token) if refresh_token else None,            "expires_at": expires_at,  # Numeric value, keep as is            "saved_at": time.time(),  # Numeric value, keep as is            "user_data": encrypt_data(json.dumps(user_data)) if user_data else None        }                try:            with open(cls.TOKEN_FILE, 'w', encoding='utf-8') as f:                json.dump(encrypted_data, f, ensure_ascii=False, indent=2)            print(f"✅ Tokens saved for user: {user_id}")            return True        except Exception as e:            print(f"❌ Failed to save tokens: {e}")            return False        @classmethod    def load_tokens(cls):        """Load tokens from file with decryption"""        try:            if not os.path.exists(cls.TOKEN_FILE):                return None                        with open(cls.TOKEN_FILE, 'r', encoding='utf-8') as f:                encrypted_data = json.load(f)                        # Decrypt sensitive data            token_data = {                "user_id": decrypt_data(encrypted_data.get("user_id")),                "access_token": decrypt_data(encrypted_data.get("access_token")),                "refresh_token": decrypt_data(encrypted_data.get("refresh_token")),                "expires_at": encrypted_data.get("expires_at"),  # Numeric value, not encrypted                "saved_at": encrypted_data.get("saved_at"),  # Numeric value, not encrypted                "user_data": json.loads(decrypt_data(encrypted_data.get("user_data"))) if encrypted_data.get("user_data") else None            }                        print(f"✅ Tokens loaded for user: {token_data.get('user_id')}")            return token_data        except Exception as e:            print(f"❌ Failed to load tokens: {e}")            return None        @classmethod    def clear_tokens(cls):        """Clear saved tokens"""        try:            if os.path.exists(cls.TOKEN_FILE):                os.remove(cls.TOKEN_FILE)            print("✅ Tokens cleared")        except Exception as e:            print(f"❌ Failed to clear tokens: {e}")        @classmethod    def is_token_expired(cls):        """Check if saved token is expired"""        token_data = cls.load_tokens()        if not token_data:            return True                current_time = time.time()        expires_at = token_data.get("expires_at", 0)                # Consider token expired if less than 5 minutes remaining        return expires_at < (current_time + 300)        @classmethod    def update_tokens(cls, access_token, refresh_token, expires_in):        """Update existing tokens"""        token_data = cls.load_tokens()        if not token_data:            return False                token_data["access_token"] = access_token        token_data["refresh_token"] = refresh_token        token_data["expires_at"] = time.time() + expires_in        token_data["saved_at"] = time.time()                try:            with open(cls.TOKEN_FILE, 'w', encoding='utf-8') as f:                json.dump(token_data, f, ensure_ascii=False, indent=2)            print(f"✅ Tokens updated for user: {token_data.get('user_id')}")            return True        except Exception as e:            print(f"❌ Failed to update tokens: {e}")            return Falseclass AccountConfig:    _instance = None        def __new__(cls):        if cls._instance is None:            cls._instance = super().__new__(cls)            cls._instance._initialized = False        return cls._instance        def __init__(self):        if not self._initialized:            # Import root config dynamically to avoid circular import            import sys            parent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))            if parent_dir not in sys.path:                sys.path.insert(0, parent_dir)                        try:                import config as root_config                self.API_BASE_URL = root_config.API_BASE_URL            except ImportError:                # Fallback                self.API_BASE_URL = "https://localhost:8443"                print(f"⚠️ Root config not found, using default API_URL: {self.API_BASE_URL}")                        # Global variables for authentication (JWT-based)            self.CURRENT_USER_ID = None            self.CURRENT_TOKEN = None            self.CURRENT_REFRESH_TOKEN = None            self.CURRENT_USER_DATA = None            self.TOKEN_EXPIRY = None                        # ✅ NEW: Session for CSRF protection            self._session = requests.Session()            self._session.verify = False  # For development            self._session.headers.update({                "X-Requested-With": "XMLHttpRequest",                "Accept": "application/json"            })                        # ✅ NEW: CSRF token            self._csrf_token = None                        # ✅ Profile data            self.USER_PROFILE_COMPLETED = False            self.PROFILE_DATA = None                        # ✅ App settings            self.LANGUAGE = "ar"            self.THEME = "light"                        # Remove old token.txt from main directory on startup            remove_old_token_txt()                        # Auto-load tokens on initialization            self._load_saved_tokens()                        self._initialized = True        def _load_saved_tokens(self):        """Load saved tokens from file on startup"""        # First try to load from token_data.json        token_data = TokenManager.load_tokens()        if token_data:            self.CURRENT_USER_ID = token_data.get("user_id")            self.CURRENT_TOKEN = token_data.get("access_token")            self.CURRENT_REFRESH_TOKEN = token_data.get("refresh_token")            self.TOKEN_EXPIRY = token_data.get("expires_at")            self.CURRENT_USER_DATA = token_data.get("user_data")                        # Update session with auth headers            if self.CURRENT_TOKEN:                self._session.headers.update({                    "Authorization": f"Bearer {self.CURRENT_TOKEN}",                    "X-User-ID": str(self.CURRENT_USER_ID)                })                        if self.CURRENT_USER_DATA and self.CURRENT_USER_DATA.get("display_name"):                self.USER_PROFILE_COMPLETED = True            elif token_data.get("profile_data"):                self.PROFILE_DATA = token_data.get("profile_data")                self.USER_PROFILE_COMPLETED = True            return                # If no token_data.json, try to load from account/token.txt (encrypted)        token = load_token_txt()        if token:            print(f"📄 account_config: Loaded token from account/token.txt (decrypted)")            self.CURRENT_TOKEN = token            # Update session with auth headers            self._session.headers.update({                "Authorization": f"Bearer {self.CURRENT_TOKEN}"            })        def _get_csrf_token_from_response(self, response):        """Extract CSRF token from response cookies or headers"""        # Check cookies        for cookie in response.cookies:            if cookie.name == "csrf_token":                self._csrf_token = cookie.value                print(f"✅ CSRF token obtained: {self._csrf_token[:20]}...")                return True                # Check headers        csrf_header = response.headers.get("X-CSRF-Token")        if csrf_header:            self._csrf_token = csrf_header            print(f"✅ CSRF token from header: {self._csrf_token[:20]}...")            return True                return False        def _get_csrf_token_from_session(self):        """Get CSRF token from session cookies"""        for cookie in self._session.cookies:            if cookie.name == "csrf_token":                return cookie.value        return self._csrf_token        def _prepare_headers(self, extra_headers: Dict[str, str] = None) -> Dict[str, str]:        """Prepare headers with CSRF protection"""        headers = {            "Content-Type": "application/json",            "X-Requested-With": "XMLHttpRequest",            "Accept": "application/json"        }                # Add auth headers        if self.CURRENT_TOKEN:            headers["Authorization"] = f"Bearer {self.CURRENT_TOKEN}"        if self.CURRENT_USER_ID:            headers["X-User-ID"] = str(self.CURRENT_USER_ID)                # Add CSRF token        csrf_token = self._get_csrf_token_from_session()        if csrf_token:            headers["X-CSRF-Token"] = csrf_token                # Add custom headers        if extra_headers:            headers.update(extra_headers)                return headers        def request(self, method: str, endpoint: str,                 data: Dict[str, Any] = None,                params: Dict[str, Any] = None,                headers: Dict[str, str] = None,                timeout: int = 30) -> requests.Response:        """        Make an HTTP request with CSRF protection and session management                Args:            method: HTTP method (GET, POST, PUT, DELETE, etc.)            endpoint: API endpoint (e.g., "/api/login")            data: JSON data for POST/PUT requests            params: Query parameters            headers: Additional headers            timeout: Request timeout in seconds                Returns:            requests.Response object        """        url = f"{self.API_BASE_URL}{endpoint}"        prepared_headers = self._prepare_headers(headers)                print(f"📤 {method} {url}")        print(f"📤 Headers: {prepared_headers}")                try:            response = self._session.request(                method=method,                url=url,                json=data,                params=params,                headers=prepared_headers,                timeout=timeout            )                        print(f"📥 Response: {response.status_code}")                        # Try to get CSRF token from response            self._get_csrf_token_from_response(response)                        return response                    except requests.exceptions.ConnectionError:            print(f"❌ Connection error to {url}")            raise        except requests.exceptions.Timeout:            print(f"❌ Timeout connecting to {url}")            raise        except Exception as e:            print(f"❌ Request error: {e}")            raise        def get(self, endpoint: str, params: Dict = None, **kwargs):        """GET request"""        return self.request("GET", endpoint, params=params, **kwargs)        def post(self, endpoint: str, data: Dict = None, **kwargs):        """POST request"""        return self.request("POST", endpoint, data=data, **kwargs)        def put(self, endpoint: str, data: Dict = None, **kwargs):        """PUT request"""        return self.request("PUT", endpoint, data=data, **kwargs)        def delete(self, endpoint: str, **kwargs):        """DELETE request"""        return self.request("DELETE", endpoint, **kwargs)        def patch(self, endpoint: str, data: Dict = None, **kwargs):        """PATCH request"""        return self.request("PATCH", endpoint, data=data, **kwargs)        def get_auth_headers(self):        """Return headers with JWT authentication token"""        return self._prepare_headers()        def clear_auth(self):        """Clear authentication data"""        self.CURRENT_USER_ID = None        self.CURRENT_TOKEN = None        self.CURRENT_REFRESH_TOKEN = None        self.CURRENT_USER_DATA = None        self.USER_PROFILE_COMPLETED = False        self.PROFILE_DATA = None        self.TOKEN_EXPIRY = None        self._csrf_token = None                # Clear session        self._session.cookies.clear()        if "Authorization" in self._session.headers:            del self._session.headers["Authorization"]        if "X-User-ID" in self._session.headers:            del self._session.headers["X-User-ID"]                TokenManager.clear_tokens()        remove_token_txt()        remove_old_token_txt()        def save_auth_data(self, user_id, access_token, refresh_token, expires_in, user_data=None):        """Save new authentication data"""        self.CURRENT_USER_ID = user_id        self.CURRENT_TOKEN = access_token        self.CURRENT_REFRESH_TOKEN = refresh_token        self.TOKEN_EXPIRY = time.time() + expires_in        self.CURRENT_USER_DATA = user_data                # Update session headers        self._session.headers.update({            "Authorization": f"Bearer {access_token}",            "X-User-ID": str(user_id)        })                # Save to file        TokenManager.save_tokens(            user_id=user_id,            access_token=access_token,            refresh_token=refresh_token,            expires_in=expires_in,            user_data=user_data        )                # Save to account/token.txt (encrypted)        save_token_txt(access_token)                if user_data and user_data.get("display_name"):            self.USER_PROFILE_COMPLETED = True        def update_tokens(self, access_token, refresh_token, expires_in):        """Update tokens after refresh"""        self.CURRENT_TOKEN = access_token        self.CURRENT_REFRESH_TOKEN = refresh_token        self.TOKEN_EXPIRY = time.time() + expires_in                # Update session headers        self._session.headers["Authorization"] = f"Bearer {access_token}"                TokenManager.update_tokens(access_token, refresh_token, expires_in)        save_token_txt(access_token)        def is_logged_in(self):        """Check login status"""        return bool(self.CURRENT_USER_ID and self.CURRENT_TOKEN and not self.is_token_expired())        def is_token_expired(self):        """Check if current token is expired"""        if self.TOKEN_EXPIRY is None:            return True                current_time = time.time()        return current_time > (self.TOKEN_EXPIRY - 300)        def get_token_info(self):        """Get information about current token"""        if not self.CURRENT_TOKEN:            return None                return {            "user_id": self.CURRENT_USER_ID,            "expires_at": self.TOKEN_EXPIRY,            "expires_in": self.TOKEN_EXPIRY - time.time() if self.TOKEN_EXPIRY else 0,            "is_expired": self.is_token_expired(),            "has_refresh_token": bool(self.CURRENT_REFRESH_TOKEN)        }        def debug_auth_status(self):        """Print debug information"""        print("\n=== AUTH DEBUG ===")        print(f"USER_ID: {self.CURRENT_USER_ID}")        print(f"ACCESS_TOKEN: {'Present' if self.CURRENT_TOKEN else 'Missing'}")        if self.CURRENT_TOKEN:            print(f"Access Token (first 20 chars): {self.CURRENT_TOKEN[:20]}...")        print(f"REFRESH_TOKEN: {'Present' if self.CURRENT_REFRESH_TOKEN else 'Missing'}")        print(f"CSRF_TOKEN: {'Present' if self._csrf_token else 'Missing'}")        print(f"TOKEN_EXPIRY: {self.TOKEN_EXPIRY}")        print(f"Is expired: {self.is_token_expired()}")        print(f"USER_DATA: {'Present' if self.CURRENT_USER_DATA else 'Missing'}")        print("==================\n")# Create a single instanceaccount_config = AccountConfig()